<style>
.ca50-contact-page{padding:0 0 70px;background:linear-gradient(180deg,#edf9ff,#fff);color:#203548}
.ca50-contact-container{width:min(1160px,calc(100% - 48px));margin:auto}
.ca50-contact-breadcrumb{display:flex;gap:12px;flex-wrap:wrap;padding:24px 0;font-size:12px;color:#607c90}
.ca50-contact-heading{max-width:720px;padding:22px 0 36px}.ca50-contact-heading>span{font-size:13px;font-weight:600;color:var(--ca-deep)}
.ca50-contact-heading h1{font-size:38px;line-height:1.3;margin:12px 0 18px}.ca50-contact-heading p{font-size:15px;line-height:1.9;color:#60788a;margin:0}
.ca50-contact-layout{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.4fr);gap:28px;align-items:start}
.ca50-contact-info{background:#e4f4ff;border:1px solid #cfe8f6;border-radius:22px;padding:30px}
.ca50-contact-layout h2{font-size:22px;margin:0 0 12px;line-height:1.4}.ca50-contact-layout>*>p{font-size:13px;line-height:1.8;color:#60788a;margin:0 0 26px}
.ca50-contact-item{display:flex;gap:16px;padding:22px 0;border-top:1px solid #cfe3ef}.ca50-contact-item:last-child{padding-bottom:0}
.ca50-contact-item>i{display:grid;place-items:center;flex:0 0 42px;height:42px;background:#fff;color:var(--ca-deep);border-radius:12px}
.ca50-contact-item h3{font-size:12px;font-weight:500;color:#587488;margin:0 0 8px}.ca50-contact-item p,.ca50-contact-item a{font-size:14px;line-height:1.8;margin:0;overflow-wrap:anywhere}.ca50-contact-item>div{min-width:0}
.ca50-contact-item .ca50-contact-directions{display:inline-block;margin-top:12px;color:var(--ca-deep);font-weight:600;font-size:12px}
.ca50-contact-form-card{padding:32px;border-radius:22px;background:#fff;border:1px solid #dcecf5;box-shadow:0 12px 40px #0876b508}
.ca50-contact-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.ca50-contact-field-wide{grid-column:1/-1}
.ca50-contact-fields label{display:block;font-size:13px;font-weight:600;margin-bottom:9px}.ca50-contact-fields input,.ca50-contact-fields textarea{display:block;width:100%;min-width:0;border:1px solid #ccdee9;background:#fbfdff;border-radius:10px;padding:13px 14px;color:#203548;font:14px/1.6 'Be Vietnam Pro',sans-serif}.ca50-contact-fields textarea{resize:vertical;min-height:140px}
.ca50-contact-fields small{display:block;margin-top:8px;font-size:11px;line-height:1.7;color:#708797}.ca50-contact-fields [aria-invalid=true]{border-color:#c43939}
.ca50-contact-form-card button{display:inline-flex;align-items:center;justify-content:center;gap:14px;padding:15px 28px;margin-top:24px;background:var(--ca-blue);color:#fff;border:0;border-radius:12px;font:600 14px 'Be Vietnam Pro',sans-serif;cursor:pointer}.ca50-contact-form-card button:hover{background:var(--ca-deep)}
.ca50-contact-page :focus-visible{outline:3px solid var(--ca-orange);outline-offset:3px}.ca50-contact-notice,.ca50-contact-error{padding:16px;margin-bottom:22px;border-radius:12px;font-size:13px;line-height:1.8}.ca50-contact-notice{background:#eaf8ee;color:#216a39}.ca50-contact-error{background:#fff1ef;color:#a72b28}.ca50-contact-error ul{margin:8px 0 0;padding-left:20px}
@media(max-width:800px){.ca50-contact-layout{grid-template-columns:1fr}.ca50-contact-heading h1{font-size:30px}.ca50-contact-heading{padding-top:10px}.ca50-contact-info{padding:24px}}
@media(max-width:480px){.ca50-contact-container{width:calc(100% - 32px)}.ca50-contact-heading h1{font-size:27px}.ca50-contact-form-card{padding:22px}.ca50-contact-fields{grid-template-columns:1fr}.ca50-contact-form-card button{width:100%}.ca50-contact-page{padding-bottom:36px}}
</style>
